create extension if not exists pgcrypto;
create table if not exists profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, email text, avatar_url text, branch text not null default 'Other', semester int not null default 1 check (semester between 1 and 8), bio text default '', is_banned boolean not null default false, created_at timestamptz not null default now());
create table if not exists posts (id uuid primary key default gen_random_uuid(), author_id uuid not null references profiles(id) on delete cascade, title text not null, subject text not null, branch text not null, semester int not null, type text not null, description text not null, link text default '', file_path text default '', file_name text default '', upvotes int not null default 0, created_at timestamptz not null default now());
create table if not exists post_upvotes (post_id uuid references posts(id) on delete cascade, user_id uuid references profiles(id) on delete cascade, primary key (post_id, user_id));
create table if not exists events (id uuid primary key default gen_random_uuid(), title text not null, club text not null, starts_at timestamptz not null, venue text not null, description text not null, category text not null, created_at timestamptz not null default now());
create table if not exists rsvps (event_id uuid references events(id) on delete cascade, user_id uuid references profiles(id) on delete cascade, primary key (event_id, user_id));
create table if not exists help_requests (id uuid primary key default gen_random_uuid(), author_id uuid not null references profiles(id) on delete cascade, title text not null, description text not null, subject text not null, tags text[] not null default '{}', solved boolean not null default false, created_at timestamptz not null default now());
create table if not exists help_replies (id uuid primary key default gen_random_uuid(), request_id uuid not null references help_requests(id) on delete cascade, author_id uuid not null references profiles(id) on delete cascade, body text not null, created_at timestamptz not null default now());
create table if not exists chat_messages (id uuid primary key default gen_random_uuid(), author_id uuid not null references profiles(id) on delete cascade, message text not null check (char_length(message) between 1 and 500), created_at timestamptz not null default now());
create table if not exists reports (id uuid primary key default gen_random_uuid(), reporter_id uuid references profiles(id) on delete set null, target_type text not null, target_id uuid not null, reason text not null, status text not null default 'open', created_at timestamptz not null default now());
alter table profiles enable row level security; alter table posts enable row level security; alter table post_upvotes enable row level security; alter table events enable row level security; alter table rsvps enable row level security; alter table help_requests enable row level security; alter table help_replies enable row level security; alter table chat_messages enable row level security; alter table reports enable row level security;
insert into storage.buckets (id, name, public) values ('posts', 'posts', false) on conflict (id) do nothing;
